exercise.solution:
"""Day 4 — loops."""


def fizzbuzz(n):
    """List for 1..n: 'Fizz' for multiples of 3, 'Buzz' for 5, 'FizzBuzz' for both, else the number as str."""
    out = []
    for i in range(1, n + 1):
        if i % 15 == 0:
            out.append("FizzBuzz")
        elif i % 3 == 0:
            out.append("Fizz")
        elif i % 5 == 0:
            out.append("Buzz")
        else:
            out.append(str(i))
    return out


def sum_of_digits(n):
    """Sum the digits of a non-negative int. sum_of_digits(1234) -> 10"""
    total = 0
    while n > 0:
        total += n % 10
        n //= 10
    return total


def is_prime(n):
    """True if n is prime."""
    if n < 2:
        return False
    i = 2
    while i * i <= n:
        if n % i == 0:
            return False
        i += 1
    return True


def primes_up_to(n):
    """All primes <= n in order. primes_up_to(10) -> [2, 3, 5, 7]"""
    return [k for k in range(2, n + 1) if is_prime(k)]


def collatz_steps(n):
    """Steps to reach 1: if even n//=2, else n=3n+1. collatz_steps(6) -> 8"""
    steps = 0
    while n != 1:
        n = n // 2 if n % 2 == 0 else 3 * n + 1
        steps += 1
    return steps


def first_index_over(nums, limit):
    """Index of the first number > limit, or -1. Use break."""
    found = -1
    for i, x in enumerate(nums):
        if x > limit:
            found = i
            break
    return found

