import day19 as ex


class Resp:
    def __init__(self, status, payload=None):
        self.status_code, self._p = status, payload

    def json(self):
        return self._p


def fake_get(responses):
    calls = []

    def get(url, timeout):
        calls.append(url)
        r = responses.pop(0)
        if isinstance(r, Exception):
            raise r
        return r
    return get, calls


DATA = {"hourly": {"time": ["2026-11-17T00:00", "2026-11-17T01:00"], "temperature_2m": [6.1, 5.8]}}


